"use client";

import { useState } from "react";
import Link from "next/link";
import { TrainFront, Loader2, ArrowRight, ArrowLeft, Mail, Key } from "lucide-react";
import axios from "axios";
import { API_BASE } from "@/lib/api";

export default function ForgotPasswordPage() {
  const [step, setStep] = useState<1 | 2>(1);
  const [email, setEmail] = useState("");
  const [otp, setOtp] = useState("");
  const [newPassword, setNewPassword] = useState("");
  
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  const handleRequestOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const res = await axios.post(`${API_BASE}/auth/forgot-password`, { email });
      if (res.data.success) {
        setStep(2);
        setSuccessMsg("OTP sent to your email.");
      }
    } catch (err: any) {
      setError(err.response?.data?.error || err.response?.data?.message || "Failed to request OTP.");
    } finally {
      setLoading(false);
    }
  };

  const handleResetPassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccessMsg(null);
    try {
      const res = await axios.post(`${API_BASE}/auth/reset-password`, { 
        email, 
        otp, 
        newPassword 
      });
      if (res.data.success) {
        setSuccessMsg("Password reset successfully!");
        // We will show the success message and a link to go back to login, handled in UI
        setStep(1); // not strictly needed, but let's just clear the form or show a final success state
      }
    } catch (err: any) {
      setError(err.response?.data?.error || err.response?.data?.message || "Failed to reset password.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-full flex-1 flex flex-col p-4 md:p-8 items-center justify-center selection:bg-rose-500/30">
      <div className="w-full max-w-md bg-card border border-subtle rounded-3xl p-8 shadow-2xl backdrop-blur-xl">
        <div className="flex flex-col items-center mb-8">
          <div className="p-3 bg-blue-500/10 rounded-xl border border-blue-500/20 mb-4">
            <Key className="w-8 h-8 text-blue-500 dark:text-blue-400" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-main">Reset Password</h1>
          <p className="text-sm text-muted mt-1 text-center">
            {step === 1 ? "Enter your email to receive an OTP" : "Enter the OTP and your new password"}
          </p>
        </div>

        {successMsg && successMsg === "Password reset successfully!" ? (
           <div className="flex flex-col items-center space-y-6">
             <div className="text-sm text-emerald-400 bg-emerald-500/10 p-4 rounded-xl border border-emerald-500/20 text-center w-full">
               {successMsg}
             </div>
             <Link href="/login" className="w-full py-3 bg-input hover:bg-card border border-subtle rounded-xl font-bold flex items-center justify-center gap-2 transition-all text-main shadow-lg">
               <ArrowLeft className="w-4 h-4" /> Back to Login
             </Link>
           </div>
        ) : (
          <>
            {step === 1 && (
              <form onSubmit={handleRequestOtp} className="space-y-5">
                <div>
                  <label className="text-xs font-semibold text-muted uppercase tracking-wider pl-1">Email Address</label>
                  <input
                    type="email"
                    value={email}
                    onChange={e => setEmail(e.target.value)}
                    className="w-full mt-1 bg-input border border-subtle rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-500 transition-all text-main"
                    placeholder="you@example.com"
                    required
                  />
                </div>

                {error && <div className="text-sm text-rose-400 bg-rose-500/10 p-3 rounded-xl border border-rose-500/20">{error}</div>}
                
                <button
                  type="submit"
                  disabled={loading || !email}
                  className="w-full py-3 bg-blue-600 hover:bg-blue-700 rounded-xl font-bold flex items-center justify-center gap-2 transition-all shadow-md text-white disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : <>Send OTP <Mail className="w-4 h-4" /></>}
                </button>
              </form>
            )}

            {step === 2 && (
              <form onSubmit={handleResetPassword} className="space-y-5">
                {successMsg && <div className="text-sm text-emerald-400 bg-emerald-500/10 p-3 rounded-xl border border-emerald-500/20">{successMsg}</div>}
                
                <div>
                  <label className="text-xs font-semibold text-muted uppercase tracking-wider pl-1">6-Digit OTP</label>
                  <input
                    type="text"
                    value={otp}
                    onChange={e => setOtp(e.target.value.replace(/[^0-9]/g, '').slice(0, 6))}
                    className="w-full mt-1 bg-input border border-subtle rounded-xl px-4 py-3 text-center text-xl tracking-[0.5em] focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-500 transition-all text-main font-mono"
                    placeholder="••••••"
                    required
                    maxLength={6}
                  />
                </div>

                <div>
                  <label className="text-xs font-semibold text-muted uppercase tracking-wider pl-1">New Password</label>
                  <input
                    type="password"
                    value={newPassword}
                    onChange={e => setNewPassword(e.target.value)}
                    className="w-full mt-1 bg-input border border-subtle rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-500 transition-all text-main"
                    placeholder="••••••••"
                    required
                    minLength={6}
                  />
                </div>

                {error && <div className="text-sm text-rose-400 bg-rose-500/10 p-3 rounded-xl border border-rose-500/20">{error}</div>}
                
                <button
                  type="submit"
                  disabled={loading || otp.length < 6 || newPassword.length < 6}
                  className="w-full py-3 bg-blue-600 hover:bg-blue-700 rounded-xl font-bold flex items-center justify-center gap-2 transition-all shadow-md text-white disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : <>Reset Password <ArrowRight className="w-4 h-4" /></>}
                </button>
              </form>
            )}

            <div className="mt-6 border-t border-subtle pt-6">
              <Link href="/login" className="flex items-center justify-center gap-2 text-sm text-muted hover:text-blue-600 dark:hover:text-blue-400 transition-colors font-medium">
                <ArrowLeft className="w-4 h-4" /> Back to Login
              </Link>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
